package servicio;
import java.sql.*;import java.time.*;import java.util.*;import config.ConexionBD;import negocio.*;import api.publica.InvitacionComunidadDTO.*;
public class InvitacionComunidadService { private static final int VIGENCIA_DIAS=14; public Invitacion enviar(long clienteId,long destino,String objetivo,String mensaje){if(clienteId<=0||destino<=0)throw new IllegalArgumentException("Los perfiles son obligatorios.");ObjetivoInvitacionComunidad o=parseObjetivo(objetivo);String limpio=limitar(mensaje);try(Connection c=ConexionBD.obtenerConexion()){c.setAutoCommit(false);try{Perfil emisor=perfilPorCliente(c,clienteId,true);Perfil receptor=perfil(c,destino,true);if(emisor.perfilId()==receptor.perfilId())throw new AutoInvitacionException();requerirHabilitados(c,emisor,receptor,o);Invitacion existente=pendiente(c,emisor.perfilId(),destino,o);if(existente!=null){c.commit();return existente;}LocalDateTime ahora=LocalDateTime.now(),expira=ahora.plusDays(VIGENCIA_DIAS);long id;try(PreparedStatement s=c.prepareStatement("INSERT INTO comunidad_invitaciones(perfil_emisor_id,perfil_destinatario_id,objetivo,estado,mensaje,fecha_invitacion,fecha_expiracion,version) VALUES(?,?,?,'PENDIENTE',?,?,?,0)",Statement.RETURN_GENERATED_KEYS)){s.setLong(1,emisor.perfilId());s.setLong(2,destino);s.setString(3,o.name());s.setString(4,limpio);s.setTimestamp(5,Timestamp.valueOf(ahora));s.setTimestamp(6,Timestamp.valueOf(expira));s.executeUpdate();try(ResultSet r=s.getGeneratedKeys()){if(!r.next())throw new IllegalStateException("No se genero la invitacion.");id=r.getLong(1);}}catch(SQLException e){if(e.getErrorCode()==1062)throw new InvitacionDuplicadaException();throw e;}evento(c,"INVITACION_COMUNIDAD_ENVIADA",id,clienteId,emisor.perfilId(),"{\"objetivo\":\""+o.name()+"\"}");c.commit();return buscarDto(c,id);}catch(RuntimeException|SQLException e){rollback(c,e);throw e;}finally{auto(c);}}catch(SQLException e){throw new RuntimeException("No se pudo enviar la invitacion.",e);}} public Listado recibidas(long clienteId){return listar(clienteId,true);} public Listado enviadas(long clienteId){return listar(clienteId,false);} public Invitacion aceptar(long clienteId,long id){return resolver(clienteId,id,EstadoInvitacionComunidad.ACEPTADA,"INVITACION_COMUNIDAD_ACEPTADA",true);} public Invitacion rechazar(long clienteId,long id){return resolver(clienteId,id,EstadoInvitacionComunidad.RECHAZADA,"INVITACION_COMUNIDAD_RECHAZADA",true);} public Invitacion cancelar(long clienteId,long id){return resolver(clienteId,id,EstadoInvitacionComunidad.CANCELADA,"INVITACION_COMUNIDAD_CANCELADA",false);} private Invitacion resolver(long clienteId,long id,EstadoInvitacionComunidad estado,String evento,boolean destinatario){if(clienteId<=0||id<=0)throw new IllegalArgumentException("La invitacion es obligatoria.");try(Connection c=ConexionBD.obtenerConexion()){c.setAutoCommit(false);try{Perfil actor=perfilPorCliente(c,clienteId,true);Registro x=registro(c,id,true);if(x==null)throw new InvitacionNoEncontradaException();long esperado=destinatario?x.destino():x.emisor();if(actor.perfilId()!=esperado)throw new InvitacionAjenaException();if(x.estado()!=EstadoInvitacionComunidad.PENDIENTE){if(x.estado()==estado){c.commit();return buscarDto(c,id);}throw new InvitacionNoPendienteException();}if(!LocalDateTime.now().isBefore(x.expira())){actualizar(c,id,EstadoInvitacionComunidad.VENCIDA);evento(c,"INVITACION_COMUNIDAD_VENCIDA",id,clienteId,actor.perfilId(),null);c.commit();throw new InvitacionVencidaException();}actualizar(c,id,estado);evento(c,evento,id,clienteId,actor.perfilId(),null);c.commit();return buscarDto(c,id);}catch(RuntimeException|SQLException e){rollback(c,e);throw e;}finally{auto(c);}}catch(SQLException e){throw new RuntimeException("No se pudo resolver la invitacion.",e);}} private Listado listar(long clienteId,boolean recibidas){try(Connection c=ConexionBD.obtenerConexion()){Perfil p=perfilPorCliente(c,clienteId,false);String q="SELECT id FROM comunidad_invitaciones WHERE "+(recibidas?"perfil_destinatario_id":"perfil_emisor_id")+"=? ORDER BY fecha_invitacion DESC,id DESC";List<Invitacion> out=new ArrayList<>();try(PreparedStatement s=c.prepareStatement(q)){s.setLong(1,p.perfilId());try(ResultSet r=s.executeQuery()){while(r.next())out.add(buscarDto(c,r.getLong(1)));}}return new Listado(out,out.size());}catch(SQLException e){throw new RuntimeException("No se pudieron consultar las invitaciones.",e);}} private void requerirHabilitados(Connection c,Perfil emisor,Perfil destino,ObjetivoInvitacionComunidad o)throws SQLException{if(!emisor.activo()||!emisor.definitivo())throw new PerfilNoHabilitadoException();if(!destino.activo()||!destino.definitivo()||!destino.disponible()||!destino.invitaciones())throw new DestinatarioNoDisponibleException();try(PreparedStatement s=c.prepareStatement("SELECT buscar_turnos,buscar_torneos FROM comunidad_preferencias WHERE cliente_id=?")){s.setLong(1,destino.clienteId());try(ResultSet r=s.executeQuery()){if(!r.next())throw new DestinatarioNoDisponibleException();boolean ok=o==ObjetivoInvitacionComunidad.COMPLETAR_PARTIDO?r.getBoolean(1):r.getBoolean(2);if(!ok)throw new ObjetivoNoHabilitadoException();}}} private Invitacion pendiente(Connection c,long emisor,long destino,ObjetivoInvitacionComunidad o)throws SQLException{try(PreparedStatement s=c.prepareStatement("SELECT id FROM comunidad_invitaciones WHERE perfil_emisor_id=? AND perfil_destinatario_id=? AND objetivo=? AND estado='PENDIENTE' FOR UPDATE")){s.setLong(1,emisor);s.setLong(2,destino);s.setString(3,o.name());try(ResultSet r=s.executeQuery()){return r.next()?buscarDto(c,r.getLong(1)):null;}}} private Invitacion buscarDto(Connection c,long id)throws SQLException{Registro x=registro(c,id,false);if(x==null)throw new InvitacionNoEncontradaException();return new Invitacion(x.id(),x.objetivo().name(),x.estado().name(),x.mensaje(),x.fecha(),x.resolucion(),x.expira(),x.version(),x.estado()==EstadoInvitacionComunidad.PENDIENTE,dtoPerfil(perfil(c,x.emisor(),false)),dtoPerfil(perfil(c,x.destino(),false)));} private api.publica.InvitacionComunidadDTO.Perfil dtoPerfil(Perfil p){return new api.publica.InvitacionComunidadDTO.Perfil(p.perfilId(),p.nombre(),p.iniciales(),p.posicion(),p.categoria(),p.color());} private Registro registro(Connection c,long id,boolean lock)throws SQLException{try(PreparedStatement s=c.prepareStatement("SELECT * FROM comunidad_invitaciones WHERE id=?"+(lock?" FOR UPDATE":""))){s.setLong(1,id);try(ResultSet r=s.executeQuery()){if(!r.next())return null;Timestamp fr=r.getTimestamp("fecha_resolucion");return new Registro(id,r.getLong("perfil_emisor_id"),r.getLong("perfil_destinatario_id"),ObjetivoInvitacionComunidad.valueOf(r.getString("objetivo")),EstadoInvitacionComunidad.valueOf(r.getString("estado")),r.getString("mensaje"),r.getTimestamp("fecha_invitacion").toLocalDateTime(),fr==null?null:fr.toLocalDateTime(),r.getTimestamp("fecha_expiracion").toLocalDateTime(),r.getLong("version"));}}} private Perfil perfilPorCliente(Connection c,long cliente,boolean lock)throws SQLException{try(PreparedStatement s=c.prepareStatement("SELECT id FROM perfiles_jugador WHERE cliente_id=?"+(lock?" FOR UPDATE":""))){s.setLong(1,cliente);try(ResultSet r=s.executeQuery()){if(!r.next())throw new PerfilNoHabilitadoException();return perfil(c,r.getLong(1),false);}}} private Perfil perfil(Connection c,long id,boolean lock)throws SQLException{String q="SELECT p.id,p.cliente_id,p.estado,p.nombre_publico,p.posicion_preferida,p.disponible_para_jugar,p.acepta_invitaciones,p.activo,cd.nombre categoria,cd.color_hex FROM perfiles_jugador p LEFT JOIN jugador_categorias jc ON jc.perfil_jugador_id=p.id AND jc.estado='VIGENTE' LEFT JOIN categorias_deportivas cd ON cd.id=jc.categoria_deportiva_id WHERE p.id=?"+(lock?" FOR UPDATE":"");try(PreparedStatement s=c.prepareStatement(q)){s.setLong(1,id);try(ResultSet r=s.executeQuery()){if(!r.next())throw new InvitacionNoEncontradaException();String n=r.getString("nombre_publico");long cliente=r.getLong("cliente_id");return new Perfil(id,n,iniciales(n),r.getString("posicion_preferida"),r.getString("categoria"),r.getString("color_hex"),r.wasNull()?null:cliente,"DEFINITIVO".equals(r.getString("estado")),r.getBoolean("disponible_para_jugar"),r.getBoolean("acepta_invitaciones"),r.getBoolean("activo"));}}} private void actualizar(Connection c,long id,EstadoInvitacionComunidad e)throws SQLException{try(PreparedStatement s=c.prepareStatement("UPDATE comunidad_invitaciones SET estado=?,fecha_resolucion=NOW(),version=version+1 WHERE id=? AND estado='PENDIENTE'")){s.setString(1,e.name());s.setLong(2,id);if(s.executeUpdate()!=1)throw new InvitacionNoPendienteException();}} private void evento(Connection c,String tipo,long invitacion,long cliente,long perfil,String detalle)throws SQLException{try(PreparedStatement s=c.prepareStatement("INSERT INTO comunidad_eventos(tipo,invitacion_id,actor_cliente_id,actor_perfil_id,detalle_json,fecha_evento) VALUES(?,?,?,?,?,NOW())")){s.setString(1,tipo);s.setLong(2,invitacion);s.setLong(3,cliente);s.setLong(4,perfil);s.setString(5,detalle);s.executeUpdate();}} private ObjetivoInvitacionComunidad parseObjetivo(String x){try{return ObjetivoInvitacionComunidad.valueOf(x==null?"":x.trim().toUpperCase(Locale.ROOT));}catch(RuntimeException e){throw new IllegalArgumentException("El objetivo de la invitacion no es valido.");}} private String limitar(String x){if(x==null||x.isBlank())return null;String y=x.trim().replaceAll("\s+"," ");if(y.length()>300)throw new IllegalArgumentException("El mensaje no puede superar 300 caracteres.");return y;} private String iniciales(String n){String[] p=n.trim().split("\s+");return(p[0].substring(0,1)+(p.length>1?p[p.length-1].substring(0,1):"")).toUpperCase(Locale.ROOT);} private void rollback(Connection c,Exception e){try{c.rollback();}catch(SQLException r){e.addSuppressed(r);}}private void auto(Connection c){try{c.setAutoCommit(true);}catch(SQLException ignored){}} private record Registro(long id,long emisor,long destino,ObjetivoInvitacionComunidad objetivo,EstadoInvitacionComunidad estado,String mensaje,LocalDateTime fecha,LocalDateTime resolucion,LocalDateTime expira,long version){} private record Perfil(long perfilId,String nombre,String iniciales,String posicion,String categoria,String color,Long clienteId,boolean definitivo,boolean disponible,boolean invitaciones,boolean activo){Perfil(long id,String n,String i,String p,String c,String co){this(id,n,i,p,c,co,null,false,false,false,false);}} public static class AutoInvitacionException extends SecurityException{public AutoInvitacionException(){super("No podes invitarte a vos mismo.");}} public static class PerfilNoHabilitadoException extends SecurityException{public PerfilNoHabilitadoException(){super("Tu perfil deportivo no esta habilitado.");}} public static class DestinatarioNoDisponibleException extends IllegalStateException{public DestinatarioNoDisponibleException(){super("El perfil ya no esta disponible para recibir invitaciones.");}} public static class ObjetivoNoHabilitadoException extends IllegalStateException{public ObjetivoNoHabilitadoException(){super("El perfil no busca ese tipo de propuesta.");}} public static class InvitacionDuplicadaException extends IllegalStateException{public InvitacionDuplicadaException(){super("Ya existe una invitacion pendiente con ese objetivo.");}} public static class InvitacionNoEncontradaException extends IllegalArgumentException{public InvitacionNoEncontradaException(){super("La invitacion no existe.");}} public static class InvitacionAjenaException extends SecurityException{public InvitacionAjenaException(){super("No podes administrar una invitacion de otra cuenta.");}} public static class InvitacionNoPendienteException extends IllegalStateException{public InvitacionNoPendienteException(){super("La invitacion ya no esta pendiente.");}} public static class InvitacionVencidaException extends IllegalStateException{public InvitacionVencidaException(){super("La invitacion vencio.");}} }
